/**
 * @file wss_client_tests.cpp
 * @brief Unit tests for ryu_ldn::network::WssClient
 *
 * These tests verify the secure WebSocket transport:
 * - Frame encoding and masking (RFC 6455 vectors)
 * - Sec-WebSocket-Accept and upgrade response parsing
 * - End-to-end against a local mbedTLS WebSocket server:
 *   fragmented frames, ping/pong, close, bad certificate, wrong host,
 *   bad token (404), bad Accept, text frames and a plaintext peer
 *
 * ## Test Strategy
 *
 * The local server runs on a thread with certificates generated by the
 * Makefile into wss_certs/ (ca.pem signs a localhost certificate;
 * other_ca.pem is an unrelated CA). It speaks the relay contract from
 * CONTRACT.md: 404 with an empty body for any auth failure, one RyuLdn
 * packet per binary message.
 */

#include <cstdio>
#include <cstring>
#include <cstdlib>
#include <atomic>
#include <chrono>
#include <csignal>
#include <string>
#include <thread>

#include <arpa/inet.h>
#include <netinet/in.h>
#include <sys/socket.h>
#include <sys/time.h>

#include <mbedtls/ctr_drbg.h>
#include <mbedtls/entropy.h>
#include <mbedtls/net_sockets.h>
#include <mbedtls/pk.h>
#include <mbedtls/ssl.h>
#include <mbedtls/x509_crt.h>

#include "network/wss_client.hpp"

using namespace ryu_ldn::network;
using namespace ryu_ldn::protocol;

// =============================================================================
// Test Framework
// =============================================================================

static int g_tests_run = 0;
static int g_tests_passed = 0;
static int g_tests_failed = 0;

// Peers close sockets under the e2e tests; never die of SIGPIPE
static struct IgnoreSigpipe {
    IgnoreSigpipe() { std::signal(SIGPIPE, SIG_IGN); }
} g_ignore_sigpipe;

#define TEST(name) \
    static void test_##name(); \
    static struct TestRegister_##name { \
        TestRegister_##name() { \
            printf("  [TEST] " #name "... "); \
            fflush(stdout); \
            g_tests_run++; \
            try { \
                test_##name(); \
                printf("PASS\n"); \
                g_tests_passed++; \
            } catch (const char* msg) { \
                printf("FAIL: %s\n", msg); \
                g_tests_failed++; \
            } \
        } \
    } g_test_register_##name; \
    static void test_##name()

#define ASSERT(cond) \
    do { \
        if (!(cond)) { \
            throw "Assertion failed: " #cond; \
        } \
    } while (0)

#define ASSERT_EQ(a, b) \
    do { \
        if ((a) != (b)) { \
            throw "Assertion failed: " #a " != " #b; \
        } \
    } while (0)

#define ASSERT_TRUE(cond) ASSERT(cond)
#define ASSERT_FALSE(cond) ASSERT(!(cond))

// =============================================================================
// Fixtures
// =============================================================================

static const char* TEST_TOKEN = "0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef";
static const char* TEST_CONSOLE_ID = "switch-1";

static ryu_ldn::config::ServerConfig make_server_config(const char* ca_file = "wss_certs/ca.pem") {
    ryu_ldn::config::ServerConfig server{};
    server.transport = ryu_ldn::config::Transport::Wss;
    std::strcpy(server.path, "/ldn");
    std::strcpy(server.console_id, TEST_CONSOLE_ID);
    std::strcpy(server.token, TEST_TOKEN);
    std::strcpy(server.ca_file, ca_file);
    return server;
}

static std::string transport_status() {
    char status[TRANSPORT_STATUS_SIZE];
    get_transport_status(status, sizeof(status));
    return status;
}

/**
 * @brief receive_packet() waits one poll per call; retry like the client's
 *        update loop does, for up to ~5 s
 */
static ClientResult receive(WssClient& client, PacketId& type, uint8_t* payload, size_t size, size_t& payload_size) {
    ClientResult result = ClientResult::Timeout;
    for (int i = 0; i < 50 && result == ClientResult::Timeout; i++) {
        result = client.receive_packet(type, payload, size, payload_size, 100);
    }
    return result;
}

// =============================================================================
// Local TLS WebSocket server
// =============================================================================

/**
 * @brief What the test server does after the TLS handshake
 */
enum class Scenario {
    Exchange,       ///< 101, fragmented packet + ping, read one client packet, close
    BadAccept,      ///< 101 with a wrong Sec-WebSocket-Accept
    TextFrame,      ///< 101, then a text frame (contract violation)
    Plaintext,      ///< No TLS at all: answer with a plain HTTP 404
    Oversized,      ///< 101, then a 100-byte packet, a 10 KB packet and a Ping
    BadHeader,      ///< 101, then a binary message that is not a RyuLdn packet
    Silent,         ///< 101, then never read again (client sends must time out)
    Drop,           ///< 101, then drop TCP without close_notify
};

/**
 * @brief One-connection mbedTLS WebSocket server on 127.0.0.1
 */
class TestServer {
public:
    explicit TestServer(Scenario scenario) : m_scenario(scenario) {
        mbedtls_net_init(&m_listen);
        mbedtls_net_bind(&m_listen, "127.0.0.1", "0", MBEDTLS_NET_PROTO_TCP);
        sockaddr_in addr{};
        socklen_t len = sizeof(addr);
        getsockname(m_listen.fd, reinterpret_cast<sockaddr*>(&addr), &len);
        m_port = ntohs(addr.sin_port);
        m_thread = std::thread([this] { run(); });
    }

    ~TestServer() {
        join();
        mbedtls_net_free(&m_listen);
    }

    /** @brief Wait for the connection to finish; results are final after this */
    void join() {
        if (m_thread.joinable()) {
            m_thread.join();
        }
    }

    uint16_t port() const { return m_port; }

    // Results observed by the server (read after join())
    bool got_pong = false;
    bool got_client_packet = false;
    bool client_frame_masked = false;
    uint8_t client_packet_type = 0;
    bool client_packet_is_echo = false;   ///< Client packet byte-identical to the ping sent
    std::string request;
    std::atomic<bool> stop{false};   ///< Ends the Silent scenario

private:
    Scenario m_scenario;
    mbedtls_net_context m_listen;
    uint16_t m_port = 0;
    std::thread m_thread;

    mbedtls_ssl_context* m_ssl = nullptr;

    void run() {
        mbedtls_net_context client;
        mbedtls_net_init(&client);
        if (mbedtls_net_accept(&m_listen, &client, nullptr, 0, nullptr) != 0) {
            return;
        }
        timeval tv{5, 0};
        setsockopt(client.fd, SOL_SOCKET, SO_RCVTIMEO, &tv, sizeof(tv));

        if (m_scenario == Scenario::Plaintext) {
            const char* reply = "HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n\r\n";
            mbedtls_net_send(&client, reinterpret_cast<const unsigned char*>(reply), std::strlen(reply));
            unsigned char sink[512];
            mbedtls_net_recv(&client, sink, sizeof(sink));
            mbedtls_net_free(&client);
            return;
        }

        mbedtls_entropy_context entropy;
        mbedtls_ctr_drbg_context drbg;
        mbedtls_ssl_config conf;
        mbedtls_ssl_context ssl;
        mbedtls_x509_crt cert;
        mbedtls_pk_context key;
        mbedtls_entropy_init(&entropy);
        mbedtls_ctr_drbg_init(&drbg);
        mbedtls_ssl_config_init(&conf);
        mbedtls_ssl_init(&ssl);
        mbedtls_x509_crt_init(&cert);
        mbedtls_pk_init(&key);

        bool ok = mbedtls_ctr_drbg_seed(&drbg, mbedtls_entropy_func, &entropy, nullptr, 0) == 0 &&
                  mbedtls_x509_crt_parse_file(&cert, "wss_certs/server.pem") == 0 &&
                  mbedtls_pk_parse_keyfile(&key, "wss_certs/server.key", nullptr) == 0 &&
                  mbedtls_ssl_config_defaults(&conf, MBEDTLS_SSL_IS_SERVER, MBEDTLS_SSL_TRANSPORT_STREAM,
                                              MBEDTLS_SSL_PRESET_DEFAULT) == 0;
        if (ok) {
            mbedtls_ssl_conf_rng(&conf, mbedtls_ctr_drbg_random, &drbg);
            ok = mbedtls_ssl_conf_own_cert(&conf, &cert, &key) == 0 && mbedtls_ssl_setup(&ssl, &conf) == 0;
        }
        if (ok) {
            mbedtls_ssl_set_bio(&ssl, &client, mbedtls_net_send, mbedtls_net_recv, nullptr);
            int ret;
            while ((ret = mbedtls_ssl_handshake(&ssl)) != 0) {
                if (ret != MBEDTLS_ERR_SSL_WANT_READ && ret != MBEDTLS_ERR_SSL_WANT_WRITE) {
                    ok = false;  // e.g. the client rejected our certificate
                    break;
                }
            }
        }
        if (ok) {
            m_ssl = &ssl;
            serve();
            if (m_scenario != Scenario::Drop) {
                mbedtls_ssl_close_notify(&ssl);
            }
        }

        mbedtls_pk_free(&key);
        mbedtls_x509_crt_free(&cert);
        mbedtls_ssl_free(&ssl);
        mbedtls_ssl_config_free(&conf);
        mbedtls_ctr_drbg_free(&drbg);
        mbedtls_entropy_free(&entropy);
        mbedtls_net_free(&client);
    }

    bool write_all(const uint8_t* data, size_t size) {
        while (size > 0) {
            int ret = mbedtls_ssl_write(m_ssl, data, size);
            if (ret <= 0) {
                return false;
            }
            data += ret;
            size -= static_cast<size_t>(ret);
        }
        return true;
    }

    bool write_str(const std::string& s) {
        return write_all(reinterpret_cast<const uint8_t*>(s.data()), s.size());
    }

    bool read_exact(uint8_t* out, size_t size) {
        while (size > 0) {
            int ret = mbedtls_ssl_read(m_ssl, out, size);
            if (ret <= 0) {
                return false;
            }
            out += ret;
            size -= static_cast<size_t>(ret);
        }
        return true;
    }

    /** @brief Send one unmasked server frame with an explicit FIN bit */
    bool write_frame(uint8_t opcode, const uint8_t* data, size_t size, bool fin = true) {
        uint8_t header[ws::MAX_HEADER_SIZE];
        size_t header_size = ws::encode_header(header, opcode, size, nullptr);
        if (!fin) {
            header[0] &= 0x7F;
        }
        return write_all(header, header_size) && (size == 0 || write_all(data, size));
    }

    /** @brief Read one client frame (unmasking it) */
    bool read_frame(uint8_t& opcode, uint8_t* payload, size_t& size) {
        uint8_t h[2];
        if (!read_exact(h, 2)) return false;
        opcode = h[0] & 0x0F;
        client_frame_masked = (h[1] & 0x80) != 0;
        size_t len = h[1] & 0x7F;
        if (len == 126) {
            uint8_t ext[2];
            if (!read_exact(ext, 2)) return false;
            len = (static_cast<size_t>(ext[0]) << 8) | ext[1];
        } else if (len == 127) {
            return false;  // Not needed by these tests
        }
        uint8_t mask[4] = {};
        if (client_frame_masked && !read_exact(mask, 4)) return false;
        if (len > size || !read_exact(payload, len)) return false;
        if (client_frame_masked) ws::apply_mask(payload, len, mask);
        size = len;
        return true;
    }

    std::string header_value(const char* name) {
        std::string needle = std::string("\r\n") + name + ": ";
        size_t pos = request.find(needle);
        if (pos == std::string::npos) return "";
        size_t start = pos + needle.size();
        return request.substr(start, request.find("\r\n", start) - start);
    }

    void serve() {
        char buf[1024];
        size_t len = 0;
        while (request.find("\r\n\r\n") == std::string::npos && len < sizeof(buf)) {
            int ret = mbedtls_ssl_read(m_ssl, reinterpret_cast<unsigned char*>(buf), sizeof(buf));
            if (ret <= 0) return;
            request.append(buf, static_cast<size_t>(ret));
        }

        // Relay contract: any auth failure is a bare 404
        if (request.compare(0, 9, "GET /ldn ") != 0 ||
            header_value("Authorization") != std::string("Bearer ") + TEST_TOKEN ||
            header_value("X-Console-Id") != TEST_CONSOLE_ID ||
            header_value("Upgrade") != "websocket") {
            write_str("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n\r\n");
            return;
        }

        char accept[32];
        ws::compute_accept(header_value("Sec-WebSocket-Key").c_str(), accept, sizeof(accept));
        if (m_scenario == Scenario::BadAccept) {
            std::strcpy(accept, "AAAAAAAAAAAAAAAAAAAAAAAAAAA=");
        }
        // 101 and the first frames go out in one record to exercise the
        // client's handling of frame bytes that arrive with the headers.
        std::string response = std::string("HTTP/1.1 101 Switching Protocols\r\n"
                                           "Upgrade: websocket\r\nConnection: Upgrade\r\n"
                                           "Sec-WebSocket-Accept: ") + accept + "\r\n\r\n";

        if (m_scenario == Scenario::TextFrame) {
            response += std::string("\x81\x02hi", 4);
            write_str(response);
            uint8_t sink[64];
            read_exact(sink, 1);  // Wait for the client to hang up
            return;
        }
        if (m_scenario == Scenario::Oversized) {
            write_str(response);
            uint8_t packet[sizeof(LdnHeader) + 10000] = {};
            encode_header(packet, PacketId::ProxyData, 100);
            write_frame(ws::OPCODE_BINARY, packet, sizeof(LdnHeader) + 100);
            encode_header(packet, PacketId::ProxyData, 10000);
            write_frame(ws::OPCODE_BINARY, packet, sizeof(packet));
            size_t ping_size = 0;
            encode_ping(packet, sizeof(packet), 0, 7, ping_size);
            write_frame(ws::OPCODE_BINARY, packet, ping_size);
            uint8_t sink[64];
            read_exact(sink, 1);
            return;
        }
        if (m_scenario == Scenario::BadHeader) {
            write_str(response);
            uint8_t garbage[sizeof(LdnHeader) + 4] = {'G', 'E', 'T', ' '};
            write_frame(ws::OPCODE_BINARY, garbage, sizeof(garbage));
            uint8_t sink[64];
            read_exact(sink, 1);
            return;
        }
        if (m_scenario == Scenario::Silent) {
            write_str(response);
            for (int i = 0; i < 300 && !stop; i++) {
                std::this_thread::sleep_for(std::chrono::milliseconds(100));
            }
            return;
        }
        if (m_scenario == Scenario::Drop) {
            write_str(response);
            return;
        }
        if (m_scenario != Scenario::Exchange) {
            write_str(response);
            uint8_t sink[64];
            read_exact(sink, 1);
            return;
        }
        if (!write_str(response)) return;

        // One RyuLdn Ping packet split over two fragments with a ping between
        uint8_t packet[64];
        size_t packet_size = 0;
        encode_ping(packet, sizeof(packet), 0, 42, packet_size);
        const uint8_t ping_payload[] = {'p', 'i', 'n', 'g'};
        if (!write_frame(ws::OPCODE_BINARY, packet, 5, false) ||
            !write_frame(ws::OPCODE_PING, ping_payload, sizeof(ping_payload)) ||
            !write_frame(ws::OPCODE_CONTINUATION, packet + 5, packet_size - 5, true)) {
            return;
        }

        // Expect the pong (echoing the ping payload), then the client packet
        uint8_t opcode = 0;
        uint8_t payload[256];
        size_t size = sizeof(payload);
        if (!read_frame(opcode, payload, size)) return;
        got_pong = opcode == ws::OPCODE_PONG && size == sizeof(ping_payload) &&
                   std::memcmp(payload, ping_payload, size) == 0;

        size = sizeof(payload);
        if (!read_frame(opcode, payload, size)) return;
        LdnHeader header{};
        if (opcode == ws::OPCODE_BINARY && size >= sizeof(header)) {
            std::memcpy(&header, payload, sizeof(header));
            got_client_packet = header.magic == PROTOCOL_MAGIC &&
                                static_cast<size_t>(header.data_size) + sizeof(header) == size;
            client_packet_type = header.type;
            client_packet_is_echo = size == packet_size && std::memcmp(payload, packet, size) == 0;
        }

        // Close 1000; the client echoes it and drops the connection
        const uint8_t close_payload[] = {0x03, 0xE8};
        write_frame(ws::OPCODE_CLOSE, close_payload, sizeof(close_payload));
        size = sizeof(payload);
        read_frame(opcode, payload, size);
    }
};

// =============================================================================
// Tests: Framing
// =============================================================================

/**
 * @test 7-bit, 16-bit and 64-bit length encodings
 */
TEST(encode_header_lengths) {
    uint8_t h[ws::MAX_HEADER_SIZE];

    ASSERT_EQ(ws::encode_header(h, ws::OPCODE_BINARY, 125, nullptr), 2u);
    ASSERT_EQ(h[0], 0x82);
    ASSERT_EQ(h[1], 125);

    ASSERT_EQ(ws::encode_header(h, ws::OPCODE_BINARY, 126, nullptr), 4u);
    ASSERT_EQ(h[1], 126);
    ASSERT_EQ(h[2], 0x00);
    ASSERT_EQ(h[3], 126);

    ASSERT_EQ(ws::encode_header(h, ws::OPCODE_BINARY, 0x10000, nullptr), 10u);
    ASSERT_EQ(h[1], 127);
    ASSERT_EQ(h[7], 0x01);
    ASSERT_EQ(h[8], 0x00);
    ASSERT_EQ(h[9], 0x00);
}

/**
 * @test Client frames carry the mask bit and key after the length
 */
TEST(encode_header_masked) {
    const uint8_t mask[4] = {0x37, 0xFA, 0x21, 0x3D};
    uint8_t h[ws::MAX_HEADER_SIZE];

    ASSERT_EQ(ws::encode_header(h, ws::OPCODE_BINARY, 300, mask), 8u);
    ASSERT_EQ(h[0], 0x82);
    ASSERT_EQ(h[1], 0x80 | 126);
    ASSERT_EQ(h[2], 0x01);
    ASSERT_EQ(h[3], 0x2C);
    ASSERT_TRUE(std::memcmp(h + 4, mask, 4) == 0);
}

/**
 * @test RFC 6455 section 5.7 masked "Hello" vector, and unmasking restores it
 */
TEST(mask_rfc_vector) {
    const uint8_t mask[4] = {0x37, 0xFA, 0x21, 0x3D};
    uint8_t data[5] = {'H', 'e', 'l', 'l', 'o'};
    const uint8_t expected[5] = {0x7F, 0x9F, 0x4D, 0x51, 0x58};

    ws::apply_mask(data, sizeof(data), mask);
    ASSERT_TRUE(std::memcmp(data, expected, sizeof(data)) == 0);
    ws::apply_mask(data, sizeof(data), mask);
    ASSERT_TRUE(std::memcmp(data, "Hello", 5) == 0);
}

// =============================================================================
// Tests: Upgrade
// =============================================================================

/**
 * @test RFC 6455 section 1.3 Sec-WebSocket-Accept vector
 */
TEST(accept_rfc_vector) {
    char accept[32];
    ASSERT_TRUE(ws::compute_accept("dGhlIHNhbXBsZSBub25jZQ==", accept, sizeof(accept)));
    ASSERT_TRUE(std::strcmp(accept, "s3pPLMBiTxaQ9kYGzzhZRbK+xOo=") == 0);
}

/**
 * @test A valid 101 passes; header names are case-insensitive
 */
TEST(upgrade_response_ok) {
    int status = 0;
    const char* response =
        "HTTP/1.1 101 Switching Protocols\r\n"
        "upgrade: WebSocket\r\n"
        "connection: upgrade\r\n"
        "sec-websocket-accept: s3pPLMBiTxaQ9kYGzzhZRbK+xOo=\r\n\r\n";
    ASSERT_TRUE(ws::check_upgrade_response(response, "s3pPLMBiTxaQ9kYGzzhZRbK+xOo=", status) == ws::UpgradeResult::Ok);
    ASSERT_EQ(status, 101);
}

/**
 * @test A wrong or missing Accept is rejected
 */
TEST(upgrade_response_bad_accept) {
    int status = 0;
    const char* wrong =
        "HTTP/1.1 101 Switching Protocols\r\n"
        "Upgrade: websocket\r\n"
        "Sec-WebSocket-Accept: s3pPLMBiTxaQ9kYGzzhZRbK+xOx=\r\n\r\n";
    ASSERT_TRUE(ws::check_upgrade_response(wrong, "s3pPLMBiTxaQ9kYGzzhZRbK+xOo=", status) == ws::UpgradeResult::BadAccept);

    const char* prefix =
        "HTTP/1.1 101 Switching Protocols\r\n"
        "Upgrade: websocket\r\n"
        "Sec-WebSocket-Accept: s3pPLMBiTxaQ9kYGzzhZRbK+xOo=extra\r\n\r\n";
    ASSERT_TRUE(ws::check_upgrade_response(prefix, "s3pPLMBiTxaQ9kYGzzhZRbK+xOo=", status) == ws::UpgradeResult::BadAccept);

    const char* missing =
        "HTTP/1.1 101 Switching Protocols\r\n"
        "Upgrade: websocket\r\n\r\n";
    ASSERT_TRUE(ws::check_upgrade_response(missing, "s3pPLMBiTxaQ9kYGzzhZRbK+xOo=", status) == ws::UpgradeResult::BadAccept);
}

/**
 * @test 404 (the relay's answer to any auth failure), bad Upgrade, garbage
 */
TEST(upgrade_response_failures) {
    int status = 0;
    ASSERT_TRUE(ws::check_upgrade_response("HTTP/1.1 404 Not Found\r\nContent-Length: 0\r\n\r\n", "x", status) ==
                ws::UpgradeResult::NotSwitching);
    ASSERT_EQ(status, 404);

    ASSERT_TRUE(ws::check_upgrade_response("HTTP/1.1 101 Switching Protocols\r\nUpgrade: h2c\r\n\r\n", "x", status) ==
                ws::UpgradeResult::BadUpgrade);

    ASSERT_TRUE(ws::check_upgrade_response("SSH-2.0-OpenSSH\r\n\r\n", "x", status) == ws::UpgradeResult::Malformed);
    ASSERT_EQ(status, 0);
}

// =============================================================================
// Tests: Configuration
// =============================================================================

/**
 * @test Missing token/console_id refuses before touching the network
 */
TEST(refuses_without_credentials) {
    auto server = make_server_config();
    server.token[0] = '\0';
    WssClient client(server);
    ASSERT_TRUE(client.initialize());
    ASSERT_TRUE(client.connect("localhost", 1, 1000) == ClientResult::ConnectionFailed);
    ASSERT_FALSE(client.is_connected());
    ASSERT_TRUE(transport_status().find("Not configured") == 0);
}

/**
 * @test A missing CA file fails closed
 */
TEST(refuses_without_ca_file) {
    WssClient client(make_server_config("wss_certs/does_not_exist.pem"));
    ASSERT_TRUE(client.initialize());
    ASSERT_TRUE(client.connect("localhost", 1, 1000) == ClientResult::TlsFailed);
    ASSERT_TRUE(transport_status().find("CA file") != std::string::npos);
}

/**
 * @test A bundle over the 64 KB cap (e.g. the full Mozilla set) fails closed
 */
TEST(refuses_oversized_ca_file) {
    std::string pem;
    if (FILE* f = std::fopen("wss_certs/ca.pem", "rb")) {
        char buf[4096];
        size_t n = std::fread(buf, 1, sizeof(buf), f);
        std::fclose(f);
        while (pem.size() <= 64 * 1024) pem.append(buf, n);
    }
    FILE* out = std::fopen("wss_certs/oversized.pem", "wb");
    ASSERT_TRUE(out != nullptr);
    std::fwrite(pem.data(), 1, pem.size(), out);
    std::fclose(out);

    WssClient client(make_server_config("wss_certs/oversized.pem"));
    ASSERT_TRUE(client.initialize());
    ASSERT_TRUE(client.connect("localhost", 1, 1000) == ClientResult::TlsFailed);
    ASSERT_TRUE(transport_status().find("over 64 KB") != std::string::npos);
}

// =============================================================================
// Tests: End-to-end against the local server
// =============================================================================

/**
 * @test Fragmented packet + interleaved ping, client packet, then close
 */
TEST(e2e_exchange) {
    {
        TestServer server(Scenario::Exchange);
        WssClient client(make_server_config());
        ASSERT_TRUE(client.initialize());
        ASSERT_TRUE(client.connect("localhost", server.port(), 5000) == ClientResult::Success);
        ASSERT_TRUE(client.is_connected());
        ASSERT_TRUE(transport_status().find("Secure") == 0);

        PacketId type;
        uint8_t payload[64];
        size_t payload_size = 0;
        ClientResult result = receive(client, type, payload, sizeof(payload), payload_size);
        ASSERT_TRUE(result == ClientResult::Success);
        ASSERT_TRUE(type == PacketId::Ping);
        ASSERT_EQ(payload_size, sizeof(PingMessage));
        ASSERT_EQ(reinterpret_cast<PingMessage*>(payload)->id, 42);

        PingMessage reply{};
        reply.id = 42;
        ASSERT_TRUE(client.send_ping(reply) == ClientResult::Success);

        // The server answers with close 1000
        result = receive(client, type, payload, sizeof(payload), payload_size);
        ASSERT_TRUE(result == ClientResult::ConnectionLost);
        ASSERT_FALSE(client.is_connected());
        ASSERT_TRUE(transport_status().find("code 1000") != std::string::npos);

        // Sticky: the reader keeps seeing ConnectionLost, never NotConnected
        ASSERT_TRUE(client.receive_packet(type, payload, sizeof(payload), payload_size, 10) == ClientResult::ConnectionLost);

        // Sends after close fail instead of writing to a dead session
        ASSERT_TRUE(client.send_ping(reply) != ClientResult::Success);
    }
}

/**
 * @test The server side saw a pong and a masked, well-formed RyuLdn packet
 */
TEST(e2e_server_view) {
    TestServer server(Scenario::Exchange);
    {
        WssClient client(make_server_config());
        ASSERT_TRUE(client.initialize());
        ASSERT_TRUE(client.connect("localhost", server.port(), 5000) == ClientResult::Success);

        PacketId type;
        uint8_t payload[64];
        size_t payload_size = 0;
        ASSERT_TRUE(receive(client, type, payload, sizeof(payload), payload_size) == ClientResult::Success);
        // Echo the server's Ping unchanged, as RyuLdnClient::process_packets does
        PingMessage reply{};
        std::memcpy(&reply, payload, sizeof(reply));
        ASSERT_TRUE(client.send_ping(reply) == ClientResult::Success);
        receive(client, type, payload, sizeof(payload), payload_size);
    }
    server.join();

    ASSERT_TRUE(server.got_pong);
    ASSERT_TRUE(server.got_client_packet);
    ASSERT_TRUE(server.client_frame_masked);
    ASSERT_EQ(server.client_packet_type, static_cast<uint8_t>(PacketId::Ping));
    ASSERT_TRUE(server.client_packet_is_echo);
    ASSERT_TRUE(server.request.find("Sec-WebSocket-Version: 13\r\n") != std::string::npos);
    ASSERT_TRUE(server.request.find("Host: localhost:") != std::string::npos);
}

