/**
 * @test A text frame breaks the contract and drops the connection
 */
TEST(e2e_text_frame_rejected) {
    TestServer server(Scenario::TextFrame);
    WssClient client(make_server_config());
    ASSERT_TRUE(client.initialize());
    // The text frame arrives with the 101 and is decoded during connect
    ClientResult result = client.connect("localhost", server.port(), 5000);
    if (result == ClientResult::Success) {
        PacketId type;
        uint8_t payload[64];
        size_t payload_size = 0;
        result = receive(client, type, payload, sizeof(payload), payload_size);
    }
    ASSERT_TRUE(result == ClientResult::ConnectionLost || result == ClientResult::NotConnected);
    ASSERT_FALSE(client.is_connected());
    ASSERT_TRUE(transport_status().find("protocol error") != std::string::npos);
}

/**
 * @test Too-large packets are consumed, never left wedging the stream
 *
 * A packet over the caller's buffer is dropped with BufferTooSmall; one over
 * the 8 KB reassembly buffer is skipped. The Ping behind them still arrives.
 */
TEST(e2e_oversized_packets_consumed) {
    TestServer server(Scenario::Oversized);
    WssClient client(make_server_config());
    ASSERT_TRUE(client.initialize());
    ASSERT_TRUE(client.connect("localhost", server.port(), 5000) == ClientResult::Success);

    PacketId type;
    uint8_t payload[64];
    size_t payload_size = 0;
    ASSERT_TRUE(receive(client, type, payload, 16, payload_size) == ClientResult::BufferTooSmall);
    ASSERT_EQ(payload_size, 100u);

    ASSERT_TRUE(receive(client, type, payload, sizeof(payload), payload_size) == ClientResult::Success);
    ASSERT_TRUE(type == PacketId::Ping);
    ASSERT_EQ(reinterpret_cast<PingMessage*>(payload)->id, 7);
    ASSERT_TRUE(client.is_connected());
}

/**
 * @test A message that is not a RyuLdn packet fails the connection cleanly
 */
TEST(e2e_bad_header_is_connection_lost) {
    TestServer server(Scenario::BadHeader);
    WssClient client(make_server_config());
    ASSERT_TRUE(client.initialize());
    ASSERT_TRUE(client.connect("localhost", server.port(), 5000) == ClientResult::Success);

    PacketId type;
    uint8_t payload[64];
    size_t payload_size = 0;
    ASSERT_TRUE(receive(client, type, payload, sizeof(payload), payload_size) == ClientResult::ConnectionLost);
    ASSERT_FALSE(client.is_connected());
    ASSERT_TRUE(client.receive_packet(type, payload, sizeof(payload), payload_size, 10) == ClientResult::ConnectionLost);
}

/**
 * @test A relay that stops reading cannot block a sender forever
 *
 * Sends stall at most send_all's 5 s writable wait, then fail with
 * ConnectionLost and the transport reports disconnected.
 */
TEST(e2e_send_stall_times_out) {
    TestServer server(Scenario::Silent);
    WssClient client(make_server_config());
    ASSERT_TRUE(client.initialize());
    ASSERT_TRUE(client.connect("localhost", server.port(), 5000) == ClientResult::Success);

    uint8_t packet[sizeof(LdnHeader) + 2000] = {};
    encode_header(packet, PacketId::ProxyData, 2000);
    const auto start = std::chrono::steady_clock::now();
    ClientResult result = ClientResult::Success;
    for (int i = 0; i < 100000 && result == ClientResult::Success; i++) {
        result = client.send_raw(packet, sizeof(packet));
    }
    const auto elapsed = std::chrono::steady_clock::now() - start;
    server.stop = true;

    ASSERT_TRUE(result == ClientResult::ConnectionLost);
    ASSERT_FALSE(client.is_connected());
    ASSERT_TRUE(elapsed < std::chrono::seconds(15));
}

/**
 * @test A dropped TCP connection surfaces as ConnectionLost on the send path
 */
TEST(e2e_peer_drop_is_connection_lost) {
    TestServer server(Scenario::Drop);
    WssClient client(make_server_config());
    ASSERT_TRUE(client.initialize());
    ASSERT_TRUE(client.connect("localhost", server.port(), 5000) == ClientResult::Success);
    server.join();

    PingMessage ping{};
    ClientResult result = ClientResult::Success;
    for (int i = 0; i < 50 && result == ClientResult::Success; i++) {
        result = client.send_ping(ping);
        std::this_thread::sleep_for(std::chrono::milliseconds(10));
    }
    ASSERT_TRUE(result == ClientResult::ConnectionLost);
    ASSERT_FALSE(client.is_connected());
    PacketId type;
    uint8_t payload[64];
    size_t payload_size = 0;
    ASSERT_TRUE(client.receive_packet(type, payload, sizeof(payload), payload_size, 10) == ClientResult::ConnectionLost);
}

/**
 * @test disconnect() while another thread is blocked in receive is safe
 *
 * The reader must come back without touching the freed TLS context
 * (build with -fsanitize=address to check), and later calls see the
 * explicit disconnect as NotConnected.
 */
TEST(e2e_disconnect_during_receive) {
    TestServer server(Scenario::Exchange);
    WssClient client(make_server_config());
    ASSERT_TRUE(client.initialize());
    ASSERT_TRUE(client.connect("localhost", server.port(), 5000) == ClientResult::Success);

    // Drain the server's first packet so the reader blocks on an idle socket
    PacketId type;
    uint8_t payload[64];
    size_t payload_size = 0;
    ASSERT_TRUE(receive(client, type, payload, sizeof(payload), payload_size) == ClientResult::Success);

    std::atomic<int> reader_result{-1};
    std::thread reader([&] {
        PacketId t;
        uint8_t p[64];
        size_t ps = 0;
        ClientResult r;
        do {
            r = client.receive_packet(t, p, sizeof(p), ps, 200);
        } while (r == ClientResult::Success || r == ClientResult::Timeout);
        reader_result = static_cast<int>(r);
    });
    std::this_thread::sleep_for(std::chrono::milliseconds(300));
    client.disconnect();
    reader.join();

    ASSERT_TRUE(reader_result == static_cast<int>(ClientResult::NotConnected) ||
                reader_result == static_cast<int>(ClientResult::ConnectionLost));
    ASSERT_FALSE(client.is_connected());
    ASSERT_TRUE(client.receive_packet(type, payload, sizeof(payload), payload_size, 10) == ClientResult::NotConnected);
}

/**
 * @test A plaintext peer never gets a request: no fallback, no token leak
 */
TEST(e2e_plaintext_refused) {
    TestServer server(Scenario::Plaintext);
    WssClient client(make_server_config());
    ASSERT_TRUE(client.initialize());
    ASSERT_TRUE(client.connect("localhost", server.port(), 5000) == ClientResult::TlsFailed);
    ASSERT_FALSE(client.is_connected());
    ASSERT_TRUE(transport_status().find("TLS: handshake failed") == 0);
}

